#include <stdio.h>
typedef struct Axis6W9bRow { unsigned int lane, epoch, shadow; int delta; } Axis6W9bRow;
typedef struct Axis6W9bAgg { unsigned int epoch[4], shadow[4]; int value[4]; } Axis6W9bAgg;
static unsigned int mix9b(unsigned int h,unsigned int v){ h ^= v + 0x9e3779b9u + (h<<6) + (h>>2); return h; }
static void clear9b(Axis6W9bAgg* a){ for(int i=0;i<4;++i){ a->epoch[i]=0u; a->shadow[i]=0u; a->value[i]=0; } }
static void absorb9b(Axis6W9bAgg* a,const Axis6W9bRow* r){ unsigned int lane=r->lane%4u; if(r->epoch<a->epoch[lane]) return; if(r->epoch>a->epoch[lane]){ a->epoch[lane]=r->epoch; a->shadow[lane]=r->shadow; a->value[lane]=r->delta; return; } if(r->shadow>a->shadow[lane]){ a->shadow[lane]=r->shadow; a->value[lane]=r->delta; } else if(r->shadow==a->shadow[lane]) a->value[lane]+=r->delta; }
static unsigned int sig9b(const Axis6W9bAgg* a){ unsigned int h=2166136261u; for(unsigned int lane=0; lane<4u; ++lane){ h=mix9b(h,lane+1u); h=mix9b(h,a->epoch[lane]); h=mix9b(h,a->shadow[lane]); h=mix9b(h,(unsigned int)(a->value[lane]&0xffff)); } return h; }
int main(void){ const Axis6W9bRow old_rows[]={{0u,3u,2u,4},{1u,2u,1u,5},{2u,4u,2u,6},{3u,3u,3u,7}}; const Axis6W9bRow new_rows[]={{0u,6u,5u,8},{1u,7u,4u,9},{2u,8u,6u,10},{3u,9u,5u,11}}; Axis6W9bAgg canonical,replayed; clear9b(&canonical); for(unsigned int i=0;i<4u;++i) absorb9b(&canonical,&new_rows[i]); clear9b(&replayed); absorb9b(&replayed,&old_rows[1]); absorb9b(&replayed,&new_rows[2]); absorb9b(&replayed,&old_rows[3]); absorb9b(&replayed,&new_rows[0]); absorb9b(&replayed,&old_rows[0]); absorb9b(&replayed,&new_rows[3]); absorb9b(&replayed,&new_rows[1]); absorb9b(&replayed,&old_rows[2]); { unsigned int sc=sig9b(&canonical), sr=sig9b(&replayed); printf("%u %u %u\n", sc, sr, (sc==sr)?1u:0u); } return 0; }
